import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-C11vx5L5.js";var i=JSON.parse(`{"path":"/english/vocabulary/plant/impact-and-evaluation/","title":"CH2.7 环境、保护与评价 | 英语","lang":"zh-CN","frontmatter":{"title":"CH2.7 环境、保护与评价","createTime":"2026-11-20T11:30:00.000Z","permalink":"/english/vocabulary/plant/impact-and-evaluation/"},"readingTime":{"minutes":32.62,"words":9786},"git":{"createdTime":1795161551000},"filePathRelative":"english/vocabulary/plant/7.impact-and-evaluation.md","headers":[],"bulletin":false}`),a={name:`7.impact-and-evaluation.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="eco-friendly" tabindex="-1"><a class="header-anchor" href="#eco-friendly"><span>Eco-friendly</span></a></h2><p class="vc-meta"><strong>/ˌiːkəʊ ˈfrendli/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>环保的，对环境友好的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>eco-friendly products</td><td>环保产品</td></tr><tr><td>an eco-friendly alternative</td><td>环保替代品</td></tr><tr><td>eco-friendly packaging</td><td>环保包装</td></tr><tr><td>more eco-friendly than</td><td>比……更环保</td></tr><tr><td>eco-friendly farming</td><td>环保农业</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares consumer spending on eco-friendly products in four countries.</p><blockquote><p>该图比较了四个国家消费者在环保产品上的支出。</p></blockquote><p><strong>Writing Task 2</strong> An eco-friendly label is meaningless unless it reflects the whole life cycle, not just disposal.</p><blockquote><p>除非环保标签反映整个生命周期而不仅是废弃环节，否则它毫无意义。</p></blockquote><p><strong>Speaking</strong> Bamboo cups feel eco-friendly, but most of them are glued together with resin.</p><blockquote><p>竹杯感觉很环保，但多数是用树脂粘起来的。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>environmentally friendly</td><td>环境友好的</td><td>正式全称，篇幅长但更严谨</td></tr><tr><td>sustainable</td><td>可持续的</td><td>强调长期可行，不只&quot;少伤害&quot;</td></tr><tr><td>green</td><td>绿色的</td><td>口语，也指&quot;缺乏经验&quot;</td></tr><tr><td>low-impact</td><td>低影响的</td><td>强调影响小，专业语境</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> eco-（生态）+ friendly（友好的）</li><li><strong>Family:</strong> eco-friendly 环保的 / ecosystem 生态系统 / ecology 生态学 / eco-tourism 生态旅游</li><li><strong>Memory Tip:</strong> eco- 是&quot;生态&quot;的万能前缀：eco-friendly、eco-tourism、eco-label。写作中它偏口语，学术文本优先用 environmentally friendly 或 sustainable。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>连字符不能省：eco-friendly ✔ / <s>eco friendly</s> 作定语时 ✘。</li><li>与 sustainable 区分：eco-friendly 只说明&quot;伤害较小&quot;，不保证长期可行。</li><li>拼写 eco-friendly，eco 后面不带连字符。</li></ul></div><div class="vocab-card"><h2 id="surroundings" tabindex="-1"><a class="header-anchor" href="#surroundings"><span>Surroundings</span></a></h2><p class="vc-meta"><strong>/səˈraʊndɪŋz/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>周围环境，周边事物（某人或某地附近的一切）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>pleasant surroundings</td><td>宜人的环境</td></tr><tr><td>in familiar surroundings</td><td>在熟悉的环境中</td></tr><tr><td>adapt to new surroundings</td><td>适应新环境</td></tr><tr><td>the immediate surroundings</td><td>周边环境</td></tr><tr><td>natural surroundings</td><td>自然环境</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows how the surroundings of the lake changed after the resort was built.</p><blockquote><p>该地图显示了度假村建成后湖泊周边环境的变化。</p></blockquote><p><strong>Writing Task 2</strong> Patients recover faster in pleasant surroundings, yet hospital design is still treated as a luxury.</p><blockquote><p>病人在宜人的环境中恢复得更快，但医院设计仍被视为奢侈品。</p></blockquote><p><strong>Speaking</strong> It took me a month to stop noticing my surroundings and actually feel at home.</p><blockquote><p>我花了一个月才不再注意周围环境，真正有了家的感觉。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>environment</td><td>环境</td><td>范围更广，含气候与社会因素</td></tr><tr><td>setting</td><td>环境，背景</td><td>强调所处的场景</td></tr><tr><td>vicinity</td><td>附近</td><td>只指地理位置邻近</td></tr><tr><td>habitat</td><td>生境</td><td>只用于动植物</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> sur-（在上、围绕）+ round（圆、周围）+ -ings</li><li><strong>Family:</strong> surroundings 环境 / surround 包围 / surrounding 周围的 / round 圆的</li><li><strong>Memory Tip:</strong> 永远是复数：surroundings 指&quot;周围一圈东西&quot;。与 environment 的区别是它更具体、更贴近日常感受。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>只用复数：<s>surrounding</s> 作名词 ✘。</li><li>与 environment 区分：surroundings 偏具体可感，environment 可指宏观议题。</li><li>拼写 surroundings，双 r。</li></ul></div><div class="vocab-card"><h2 id="conservation" tabindex="-1"><a class="header-anchor" href="#conservation"><span>Conservation</span></a></h2><p class="vc-meta"><strong>/ˌkɒnsəˈveɪʃn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>保护，保存（自然资源、文物、能源）</li><li>节约（能源、水）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>nature conservation</td><td>自然保护</td></tr><tr><td>conservation area</td><td>保护区</td></tr><tr><td>energy conservation</td><td>节能</td></tr><tr><td>conservation efforts</td><td>保护工作</td></tr><tr><td>wildlife conservation</td><td>野生生物保护</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows spending on conservation compared with spending on visitor facilities.</p><blockquote><p>该图比较了保护工作与游客设施上的支出。</p></blockquote><p><strong>Writing Task 2</strong> Conservation succeeds when local people benefit from it, not when it is imposed from outside.</p><blockquote><p>只有当当地人从中受益，而非由外界强加时，保护才会成功。</p></blockquote><p><strong>Speaking</strong> The conservation area behind the village is the only reason the river still has fish.</p><blockquote><p>村子后面的保护区是这条河还有鱼的唯一原因。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>preservation</td><td>保存</td><td>强调保持原样，不强调合理利用</td></tr><tr><td>protection</td><td>保护</td><td>强调免受伤害，范围更广</td></tr><tr><td>management</td><td>管理</td><td>强调人为经营，未必是保护</td></tr><tr><td>sustainability</td><td>可持续性</td><td>强调长期可行，不是具体行动</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> con-（共同）+ servare（守护）+ -ation</li><li><strong>Family:</strong> conservation 保护 / conserve 保护；节约 / conservative 保守的 / preserve 保存</li><li><strong>Memory Tip:</strong> 三个 -serve 词：conserve 是&quot;省着用&quot;，preserve 是&quot;原样留住&quot;，reserve 是&quot;留着备用&quot;。conservation 兼具&quot;保护&quot;与&quot;节约&quot;两义。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：<s>conservations</s> ✘。</li><li>与 preservation 区分：conservation 允许合理利用，preservation 强调完全不动。</li><li>拼写 conservation，注意 -serv-。</li></ul></div><div class="vocab-card"><h2 id="preserve" tabindex="-1"><a class="header-anchor" href="#preserve"><span>Preserve</span></a></h2><p class="vc-meta"><strong>/prɪˈzɜːv/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：保护，维护（使保持原状）；保存（食物）</li><li>名词：保护区；果酱；专属领域</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>preserve biodiversity</td><td>保护生物多样性</td></tr><tr><td>preserve historic buildings</td><td>保护历史建筑</td></tr><tr><td>a nature preserve</td><td>自然保护区</td></tr><tr><td>preserved food</td><td>腌制食品</td></tr><tr><td>preserve the status quo</td><td>维持现状</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the area designated as a nature preserve in 1998.</p><blockquote><p>该地图显示了 1998 年被划为自然保护区的区域。</p></blockquote><p><strong>Writing Task 2</strong> Preserving habitats is more effective than breeding endangered species in captivity.</p><blockquote><p>保护生境比在圈养条件下繁育濒危物种更有效。</p></blockquote><p><strong>Speaking</strong> They preserved the old station building and turned it into a café — surprisingly well done.</p><blockquote><p>他们保留了老车站建筑，改成咖啡馆，做得意外地好。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>conserve</td><td>节约；保护</td><td>强调合理利用，不浪费</td></tr><tr><td>protect</td><td>保护</td><td>强调免受伤害，最通用</td></tr><tr><td>maintain</td><td>维持</td><td>强调保持状态</td></tr><tr><td>retain</td><td>保留</td><td>强调不失去，多用于抽象</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> pre-（预先）+ servare（守护）</li><li><strong>Family:</strong> preserve 保护；果酱 / preservation 保存 / preservative 防腐剂 / reserve 保留</li><li><strong>Memory Tip:</strong> servare 是&quot;守护&quot;：preserve 提前守住，reserve 留下来备用，conserve 省着用。三词对比最有效。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 conserve 区分：preserve 强调&quot;保持原样&quot;，conserve 强调&quot;节约使用&quot;。</li><li>名词&quot;保护区&quot;是 preserve：a nature preserve。</li><li>拼写 preserve，中间是 -serve。</li></ul></div><div class="vocab-card"><h2 id="protect" tabindex="-1"><a class="header-anchor" href="#protect"><span>Protect</span></a></h2><p class="vc-meta"><strong>/prəˈtekt/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>保护，防护（使免受伤害、损失）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>protect against</td><td>防止，抵御</td></tr><tr><td>protect from</td><td>保护免受</td></tr><tr><td>protect the environment</td><td>保护环境</td></tr><tr><td>legally protected</td><td>受法律保护的</td></tr><tr><td>protected area</td><td>保护区</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the share of land protected under national law in each region.</p><blockquote><p>该图显示了各区域受国家法律保护的土地占比。</p></blockquote><p><strong>Writing Task 2</strong> Protecting a wetland is cheaper than replacing the flood control it provides for free.</p><blockquote><p>保护湿地比替代它免费提供的防洪功能更便宜。</p></blockquote><p><strong>Speaking</strong> The fence protects the seedlings from rabbits, but not from my neighbour&#39;s dog.</p><blockquote><p>栅栏能防兔子啃幼苗，但防不住邻居的狗。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>safeguard</td><td>保障</td><td>更正式，多用于权利与制度</td></tr><tr><td>shield</td><td>遮蔽</td><td>强调挡住具体威胁</td></tr><tr><td>defend</td><td>保卫</td><td>多用于人、领土与立场</td></tr><tr><td>preserve</td><td>保存</td><td>强调保持原状，不只防伤害</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> pro-（在前）+ tegere（覆盖）→ 在前面挡住</li><li><strong>Family:</strong> protect 保护 / protection 保护 / protective 保护的 / detect 察觉（同源&quot;揭开&quot;）</li><li><strong>Memory Tip:</strong> tegere 是&quot;覆盖&quot;：protect 是&quot;在前面盖住&quot;，detect 是&quot;把盖子揭开&quot;（所以是察觉）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词分工：protect from 具体伤害，protect against 风险与攻击。</li><li>名词是 protection：<s>protectment</s> ✘。</li><li>及物动词：protect the forest ✔。</li></ul></div><div class="vocab-card"><h2 id="counterbalance" tabindex="-1"><a class="header-anchor" href="#counterbalance"><span>Counterbalance</span></a></h2><p class="vc-meta"><strong>/ˌkaʊntəˈbæləns/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：抵消，平衡（相反的力量或影响）</li><li>名词：平衡力，抗衡因素</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>counterbalance the effect</td><td>抵消影响</td></tr><tr><td>counterbalance each other</td><td>相互抵消</td></tr><tr><td>a counterbalance to</td><td>对……的制衡</td></tr><tr><td>serve as a counterbalance</td><td>起平衡作用</td></tr><tr><td>counterbalancing force</td><td>平衡力量</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how tree planting counterbalances part of the city&#39;s emissions.</p><blockquote><p>该图显示了植树如何抵消这座城市的部分排放。</p></blockquote><p><strong>Writing Task 2</strong> Green space counterbalances some of the heat of dense housing, but it cannot replace good design.</p><blockquote><p>绿地能抵消高密度住宅的部分热量，但无法替代好的设计。</p></blockquote><p><strong>Speaking</strong> The extra cost is counterbalanced by the fuel savings, so it evens out in about four years.</p><blockquote><p>额外的花费被省下的燃料费抵消，大约四年就持平了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>offset</td><td>抵消</td><td>多用于排放、成本，政策语境常用</td></tr><tr><td>balance</td><td>平衡</td><td>更泛，不强调&quot;相反力量&quot;</td></tr><tr><td>compensate for</td><td>补偿</td><td>强调弥补损失</td></tr><tr><td>neutralise</td><td>中和</td><td>多用于化学与抽象效果</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> counter-（相反）+ balance（平衡）</li><li><strong>Family:</strong> counterbalance 抵消 / counter- 反……（counteract 抵消、counterpart 对应物）/ balance 平衡</li><li><strong>Memory Tip:</strong> counter- 表示&quot;反向&quot;：counteract 是反向作用，counterbalance 是反向的重量。碳排放语境里 offset 更常用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>及物动词：Trees counterbalance emissions ✔。</li><li>与 offset 区分：offset 更常用于可量化的排放与成本。</li><li>拼写 counterbalance 连写。</li></ul></div><div class="vocab-card"><h2 id="impact" tabindex="-1"><a class="header-anchor" href="#impact"><span>Impact</span></a></h2><p class="vc-meta"><strong>/ˈɪmpækt/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：影响，作用；冲击，撞击</li><li>动词：影响；（/ɪmˈpækt/）撞击</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>have an impact on</td><td>对……有影响</td></tr><tr><td>environmental impact</td><td>环境影响</td></tr><tr><td>a significant impact</td><td>显著影响</td></tr><tr><td>impact assessment</td><td>影响评估</td></tr><tr><td>reduce the impact of</td><td>减轻……的影响</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the impact of tourism on water use in coastal towns.</p><blockquote><p>该图显示了旅游业对沿海城镇用水的影响。</p></blockquote><p><strong>Writing Task 2</strong> The environmental impact of flying is large per passenger, which is why frequent flyers are the focus of policy.</p><blockquote><p>航空的人均环境影响很大，因此常旅客成为政策的焦点。</p></blockquote><p><strong>Speaking</strong> Moving closer to work had a bigger impact on my wellbeing than any amount of exercise.</p><blockquote><p>搬到离公司更近的地方，对我身心状态的影响超过任何锻炼。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>effect</td><td>影响</td><td>中性，常与 on 连用</td></tr><tr><td>influence</td><td>影响</td><td>多指潜移默化的作用</td></tr><tr><td>consequence</td><td>后果</td><td>强调结果，常含负面</td></tr><tr><td>collision</td><td>碰撞</td><td>只对应&quot;撞击&quot;义项</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>impactus</em> ← in-（向内）+ pangere（钉入）</li><li><strong>Family:</strong> impact 影响；撞击 / impactful 有影响力的 / impinge 侵犯（同源）</li><li><strong>Memory Tip:</strong> 原义是&quot;钉进去&quot;，所以&quot;影响&quot;就像钉进事物内部。名词重音在前 /ˈɪmpækt/，动词重音在后 /ɪmˈpækt/。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>搭配是 have an impact <strong>on</strong>，不用 <s>impact to</s>。</li><li>名词可数：a significant impact、impacts on wildlife。</li><li>动词重音与名词不同，口语考试注意。</li></ul></div><div class="vocab-card"><h2 id="ruin" tabindex="-1"><a class="header-anchor" href="#ruin"><span>Ruin</span></a></h2><p class="vc-meta"><strong>/ˈruːɪn/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：毁坏，破坏；使破产</li><li>名词：毁灭，破败；废墟（ruins）；破产</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>ruin the landscape</td><td>破坏景观</td></tr><tr><td>be ruined by</td><td>被……毁掉</td></tr><tr><td>in ruins</td><td>成为废墟</td></tr><tr><td>financial ruin</td><td>破产</td></tr><tr><td>the ruins of a temple</td><td>寺庙废墟</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows how quarrying ruined the valley within thirty years.</p><blockquote><p>该地图显示了采石如何在三十年内毁掉这条河谷。</p></blockquote><p><strong>Writing Task 2</strong> A single bad harvest can ruin a smallholder who has no insurance and no savings.</p><blockquote><p>一次歉收就能毁掉一个没有保险也没有储蓄的小农。</p></blockquote><p><strong>Speaking</strong> The rain ruined the picnic, so we ate inside and pretended it was fine.</p><blockquote><p>下雨毁了野餐，我们就在屋里吃，假装一切都好。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>destroy</td><td>摧毁</td><td>程度更彻底，强调不复存在</td></tr><tr><td>damage</td><td>损坏</td><td>程度较轻，可修复</td></tr><tr><td>spoil</td><td>破坏</td><td>口语，多用于心情与计划</td></tr><tr><td>wreck</td><td>毁掉</td><td>口语，多用于车辆与计划</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>ruina</em>（倒塌）← <em>ruere</em>（坠落）</li><li><strong>Family:</strong> ruin 毁坏；废墟 / ruined 破败的 / ruinous 毁灭性的</li><li><strong>Memory Tip:</strong> 原义是&quot;倒塌&quot;，所以 in ruins 是&quot;成废墟&quot;。注意 ruin 与 destroy 的程度差别：ruin 常指&quot;败坏、毁掉价值&quot;，destroy 是&quot;彻底消灭&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数名词指&quot;废墟&quot;常用复数：the ruins of Pompeii。</li><li>不可数指&quot;破产、毁灭&quot;：on the brink of ruin。</li><li>拼写 ruin，两个音节 /ˈruːɪn/。</li></ul></div><div class="vocab-card"><h2 id="demolish" tabindex="-1"><a class="header-anchor" href="#demolish"><span>Demolish</span></a></h2><p class="vc-meta"><strong>/dɪˈmɒlɪʃ/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>拆除，拆毁（建筑物）</li><li>推翻，驳倒（论点、理论）；彻底击败</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>demolish a building</td><td>拆除建筑</td></tr><tr><td>demolish an argument</td><td>驳倒一个论点</td></tr><tr><td>be demolished to make way for</td><td>被拆掉以让位于</td></tr><tr><td>demolition work</td><td>拆除工程</td></tr><tr><td>demolition waste</td><td>建筑垃圾</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the houses demolished to build the ring road.</p><blockquote><p>该地图显示了为修环路而拆除的房屋。</p></blockquote><p><strong>Writing Task 2</strong> Demolishing usable buildings wastes the carbon already invested in their concrete and steel.</p><blockquote><p>拆除仍可使用的建筑，浪费了已投入其混凝土与钢材中的碳。</p></blockquote><p><strong>Speaking</strong> They demolished the old cinema in a week and put up a car park that nobody uses.</p><blockquote><p>他们一周就拆了老电影院，盖了个没人用的停车场。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>knock down</td><td>拆倒</td><td>口语，最常用</td></tr><tr><td>tear down</td><td>拆除</td><td>口语，强调拉扯倒下</td></tr><tr><td>dismantle</td><td>拆卸</td><td>强调按部件拆开，可再利用</td></tr><tr><td>destroy</td><td>摧毁</td><td>泛指，不限建筑</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>demoliri</em>（推倒）← de-（向下）+ moliri（建造）</li><li><strong>Family:</strong> demolish 拆除 / demolition 拆除 / demolisher 拆除者</li><li><strong>Memory Tip:</strong> de-（向下）+ moliri（建造）＝把建起来的弄下去。名词 demolition 拼写会变（ish → ition），是常考点。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>及物动词：demolish the building ✔ / <s>demolish down</s> ✘。</li><li>名词是 demolition：<s>demolishment</s> 极少用。</li><li>拼写 demolish，不是 <s>demolisch</s>。</li></ul></div><div class="vocab-card"><h2 id="destruct" tabindex="-1"><a class="header-anchor" href="#destruct"><span>Destruct</span></a></h2><p class="vc-meta"><strong>/dɪˈstrʌkt/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>破坏，毁灭（多用于 self-destruct 自毁）</li><li>名词形式为 destruction，形容词为 destructive</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>self-destruct</td><td>自毁</td></tr><tr><td>a self-destruct button</td><td>自毁按钮</td></tr><tr><td>destruct sequence</td><td>自毁程序</td></tr><tr><td>destruction of habitat</td><td>生境破坏</td></tr><tr><td>destructive practices</td><td>破坏性做法</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how coastal development led to the destruction of the dune system.</p><blockquote><p>该图显示了沿海开发如何导致沙丘系统的破坏。</p></blockquote><p><strong>Writing Task 2</strong> Short-term profit is often destructive in the long run, especially where soil and water are involved.</p><blockquote><p>短期利润从长期看常具破坏性，涉及土壤与水时尤其如此。</p></blockquote><p><strong>Speaking</strong> The message was set to self-destruct, which felt dramatic for a lunch invitation.</p><blockquote><p>那条消息设置了自毁，对一条午饭邀约来说有点戏剧化。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>destroy</td><td>摧毁</td><td>常用动词，直接带宾语</td></tr><tr><td>damage</td><td>损害</td><td>程度较轻，可修复</td></tr><tr><td>devastation</td><td>毁坏</td><td>名词，强调大面积破坏</td></tr><tr><td>ruin</td><td>毁掉</td><td>强调价值与状态被败坏</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> de-（向下、反）+ struere（建造）→ 拆掉建起来的东西</li><li><strong>Family:</strong> destruct 破坏 / destruction 破坏 / destructive 破坏性的 / structure 结构 / construct 建造</li><li><strong>Memory Tip:</strong> struere 是&quot;建造&quot;：construct 是建，destruct 是拆，structure 是建起来的东西。日常动词用 destroy，名词用 destruction。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>destruct 作独立动词很少见，常用 destroy；self-destruct 才是固定搭配。</li><li>名词是 destruction：<s>destructment</s> ✘。</li><li>与 damage 区分：destruction 程度更重，常不可逆。</li></ul></div><div class="vocab-card"><h2 id="extinguish" tabindex="-1"><a class="header-anchor" href="#extinguish"><span>Extinguish</span></a></h2><p class="vc-meta"><strong>/ɪkˈstɪŋɡwɪʃ/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>熄灭，扑灭（火、光）</li><li>消灭，使消亡（希望、生命、权利）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>extinguish a fire</td><td>扑灭火灾</td></tr><tr><td>extinguish a species</td><td>使物种灭绝</td></tr><tr><td>extinguish hope</td><td>使希望破灭</td></tr><tr><td>fire extinguisher</td><td>灭火器</td></tr><tr><td>be extinguished</td><td>被扑灭</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how quickly fires are extinguished in managed and unmanaged forests.</p><blockquote><p>该图显示了管理林与未管理林中火灾被扑灭的速度。</p></blockquote><p><strong>Writing Task 2</strong> Fire suppression can extinguish small fires but leaves fuel to build up for a much larger one.</p><blockquote><p>灭火能扑灭小火，却会让可燃物积累，最终酿成更大的火。</p></blockquote><p><strong>Speaking</strong> Nothing extinguishes a conversation faster than someone checking their phone.</p><blockquote><p>没有什么比有人看手机更快地终结一场对话了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>put out</td><td>扑灭</td><td>口语，最常用</td></tr><tr><td>quench</td><td>熄灭</td><td>多用于口渴与火，文学色彩</td></tr><tr><td>suppress</td><td>压制</td><td>强调控制，不一定是火</td></tr><tr><td>eradicate</td><td>根除</td><td>强调彻底清除</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>exstinguere</em> ← ex-（出）+ stinguere（刺、熄灭）</li><li><strong>Family:</strong> extinguish 扑灭 / extinguisher 灭火器 / extinct 灭绝的 / extinction 灭绝</li><li><strong>Memory Tip:</strong> extinguish 与 extinct 同源：火被扑灭是 extinguish，物种被灭是 extinct。fire extinguisher 是&quot;灭火器&quot;，写作中很实用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>及物动词：extinguish the fire ✔ / <s>the fire extinguished</s>（除非被动）。</li><li>名词是 extinction（灭绝）与 extinguisher（灭火器），别混。</li><li>拼写 extinguish，中间是 -ting-。</li></ul></div><div class="vocab-card"><h2 id="perish" tabindex="-1"><a class="header-anchor" href="#perish"><span>Perish</span></a></h2><p class="vc-meta"><strong>/ˈperɪʃ/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>死亡，丧生（尤指非正常死亡）</li><li>（材料、食物）老化，腐烂</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>perish in a fire</td><td>死于火灾</td></tr><tr><td>perish at sea</td><td>葬身海上</td></tr><tr><td>perishable goods</td><td>易腐货物</td></tr><tr><td>perish from hunger</td><td>饿死</td></tr><tr><td>those who perished</td><td>遇难者</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how many people perished in weather-related disasters each decade.</p><blockquote><p>该图显示了每十年天气相关灾害的死亡人数。</p></blockquote><p><strong>Writing Task 2</strong> Crops that perish within days force farmers to sell immediately, at whatever price buyers offer.</p><blockquote><p>几天内就会腐烂的作物迫使农民立即出售，无论买家出什么价。</p></blockquote><p><strong>Speaking</strong> Without shade, the seedlings perished within a week of planting.</p><blockquote><p>没有遮阴，幼苗种下后一周内就死了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>die</td><td>死</td><td>中性通用，最口语</td></tr><tr><td>pass away</td><td>去世</td><td>委婉说法，用于人</td></tr><tr><td>be killed</td><td>丧生</td><td>强调外力致死</td></tr><tr><td>decay</td><td>腐烂</td><td>只对应&quot;腐坏&quot;义项</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>perire</em>（消亡）← per-（彻底）+ ire（走）</li><li><strong>Family:</strong> perish 死亡；腐坏 / perishable 易腐的 / perished 遇难的</li><li><strong>Memory Tip:</strong> ire 是&quot;走&quot;：perish 是&quot;彻底走掉&quot;。perishable goods 是&quot;易腐货物&quot;，物流与食品话题的高频词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不及物动词：Many perished ✔ / <s>perished them</s> ✘。</li><li>用于灾难与事故，日常&quot;死&quot;用 die。</li><li>拼写 perish，不是 <s>perrish</s>。</li></ul></div><div class="vocab-card"><h2 id="extinction" tabindex="-1"><a class="header-anchor" href="#extinction"><span>Extinction</span></a></h2><p class="vc-meta"><strong>/ɪkˈstɪŋkʃn/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>灭绝，绝种；（习俗、职业等的）消亡</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>face extinction</td><td>面临灭绝</td></tr><tr><td>on the brink of extinction</td><td>濒临灭绝</td></tr><tr><td>mass extinction</td><td>大灭绝</td></tr><tr><td>prevent extinction</td><td>防止灭绝</td></tr><tr><td>extinction rate</td><td>灭绝速率</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the extinction rate of freshwater species over the past century.</p><blockquote><p>该图显示了过去一个世纪淡水物种的灭绝速率。</p></blockquote><p><strong>Writing Task 2</strong> Species loss is now driven mainly by habitat destruction rather than by direct hunting.</p><blockquote><p>如今物种丧失主要由生境破坏驱动，而非直接捕猎。</p></blockquote><p><strong>Speaking</strong> The bird was down to forty individuals before anybody seriously talked about extinction.</p><blockquote><p>这种鸟只剩四十只时，人们才开始认真讨论灭绝问题。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>disappearance</td><td>消失</td><td>语气较轻，不一定是物种灭绝</td></tr><tr><td>die-out</td><td>绝迹</td><td>口语，非正式</td></tr><tr><td>eradication</td><td>根除</td><td>强调人为彻底清除</td></tr><tr><td>decline</td><td>减少</td><td>数量下降，未必归零</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> ex-（出）+ stinguere（熄灭）+ -tion</li><li><strong>Family:</strong> extinction 灭绝 / extinct 灭绝的 / extinguish 扑灭 / distinct 不同的（同源&quot;分开&quot;）</li><li><strong>Memory Tip:</strong> 与 extinguish 同源——火被&quot;熄灭&quot;了，物种就&quot;灭绝&quot;了。形容词是 extinct：an extinct species。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>不可数：<s>extinctions</s> 指多次灭绝事件时可数（mass extinctions）。</li><li>形容词是 extinct，名词是 extinction：<s>extinct species</s> ✔，<s>extinction species</s> ✘。</li><li>拼写 extinction，注意 -nction。</li></ul></div><div class="vocab-card"><h2 id="undermine" tabindex="-1"><a class="header-anchor" href="#undermine"><span>Undermine</span></a></h2><p class="vc-meta"><strong>/ˌʌndəˈmaɪn/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>逐渐削弱，暗中破坏（信心、权威、努力）</li><li>掏空（地基），在下方挖空</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>undermine confidence</td><td>削弱信心</td></tr><tr><td>undermine the argument</td><td>削弱论点</td></tr><tr><td>undermine efforts</td><td>使努力付诸东流</td></tr><tr><td>be undermined by</td><td>被……削弱</td></tr><tr><td>undermine authority</td><td>削弱权威</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how repeated droughts undermined gains in crop yields.</p><blockquote><p>该图显示了反复干旱如何削弱了作物产量的提升。</p></blockquote><p><strong>Writing Task 2</strong> Subsidising fossil fuels undermines the very climate policy the same government claims to support.</p><blockquote><p>补贴化石燃料，恰恰削弱了同一政府声称支持的气候政策。</p></blockquote><p><strong>Speaking</strong> Constant changes of plan undermined everyone&#39;s confidence in the project.</p><blockquote><p>计划反复变动削弱了所有人对这个项目的信心。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>weaken</td><td>削弱</td><td>中性，不含&quot;暗中&quot;意味</td></tr><tr><td>erode</td><td>侵蚀</td><td>强调缓慢、渐进</td></tr><tr><td>sabotage</td><td>蓄意破坏</td><td>强调故意与恶意</td></tr><tr><td>jeopardise</td><td>危及</td><td>强调使面临风险</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> under（下面）+ mine（挖掘）</li><li><strong>Family:</strong> undermine 削弱 / mine 矿；挖掘 / mining 采矿 / undermine 掏空地基</li><li><strong>Memory Tip:</strong> 字面是&quot;从下面挖空&quot;——地基被掏空，墙就慢慢塌。所以&quot;削弱信心&quot;用它，比 weaken 多一层&quot;悄悄发生&quot;的意味。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>及物动词：undermine confidence ✔。</li><li>与 weaken 区分：undermine 强调渐进且常不易察觉。</li><li>拼写 undermine 连写，不写成 <s>under-mine</s>。</li></ul></div><div class="vocab-card"><h2 id="infringe" tabindex="-1"><a class="header-anchor" href="#infringe"><span>Infringe</span></a></h2><p class="vc-meta"><strong>/ɪnˈfrɪndʒ/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>侵犯，侵害（权利、隐私）</li><li>违反（法律、规定）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>infringe a right</td><td>侵犯权利</td></tr><tr><td>infringe on privacy</td><td>侵犯隐私</td></tr><tr><td>infringe copyright</td><td>侵犯版权</td></tr><tr><td>infringe regulations</td><td>违反规定</td></tr><tr><td>infringement of</td><td>对……的侵犯</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how many cases involved infringement of environmental regulations.</p><blockquote><p>该图显示了多少案件涉及违反环境法规。</p></blockquote><p><strong>Writing Task 2</strong> Monitoring private messages to detect tax evasion infringes privacy far beyond what the gain justifies.</p><blockquote><p>为查处逃税而监控私人信息，对隐私的侵犯远超其收益所能辩护的程度。</p></blockquote><p><strong>Speaking</strong> Filming inside the gallery infringes the artists&#39; rights, even if nobody stops you.</p><blockquote><p>在画廊里拍摄侵犯了艺术家的权利，即使没人拦你。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>violate</td><td>违反</td><td>语气更强，多用于法律与权利</td></tr><tr><td>breach</td><td>违反</td><td>多用于合同、协议</td></tr><tr><td>encroach on</td><td>侵占</td><td>强调逐步蚕食</td></tr><tr><td>trespass</td><td>非法侵入</td><td>指进入他人土地</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>infringere</em>（打破）← in-（进入）+ frangere（打碎）</li><li><strong>Family:</strong> infringe 侵犯 / infringement 侵权 / fragile 易碎的（同源 frangere）</li><li><strong>Memory Tip:</strong> frangere 是&quot;打碎&quot;：infringe 就是&quot;把规则打破&quot;。名词 infringement 常用于版权与专利语境。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词：infringe <strong>on</strong> privacy；直接接宾语时多用权利与法规（infringe copyright）。</li><li>名词是 infringement，不是 <s>infringement</s>（拼写注意 -ge-）。</li><li>拼写 infringe，结尾是 -nge。</li></ul></div><div class="vocab-card"><h2 id="seasonal" tabindex="-1"><a class="header-anchor" href="#seasonal"><span>Seasonal</span></a></h2><p class="vc-meta"><strong>/ˈsiːzənl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>季节性的，随季节变化的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>seasonal work</td><td>季节性工作</td></tr><tr><td>seasonal variation</td><td>季节性变化</td></tr><tr><td>seasonal workers</td><td>季节性工人</td></tr><tr><td>seasonal produce</td><td>时令农产品</td></tr><tr><td>seasonal flooding</td><td>季节性洪水</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows strong seasonal variation in tourist numbers, peaking in August.</p><blockquote><p>该图显示了游客人数明显的季节性波动，八月达到峰值。</p></blockquote><p><strong>Writing Task 2</strong> Seasonal work gives flexibility but makes it hard for workers to plan a year ahead.</p><blockquote><p>季节性工作带来灵活性，却让工人难以提前一年做规划。</p></blockquote><p><strong>Speaking</strong> Buying seasonal produce is cheaper and tastes better — it&#39;s not really a sacrifice.</p><blockquote><p>买时令农产品更便宜也更好吃，其实算不上牺牲。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>periodic</td><td>周期性的</td><td>强调规律重复，不限季节</td></tr><tr><td>cyclical</td><td>周期循环的</td><td>多用于经济与产业</td></tr><tr><td>intermittent</td><td>间歇的</td><td>强调时断时续</td></tr><tr><td>annual</td><td>年度的</td><td>指每年一次，不指季节波动</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> season（季节）+ -al</li><li><strong>Family:</strong> seasonal 季节性的 / season 季节 / seasonality 季节性 / off-season 淡季</li><li><strong>Memory Tip:</strong> 写作中描述图表波动，seasonal variation 比 changes by season 更专业。注意 seasonal 与 seasonable（合时令的）不同。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 seasonable 区分：seasonal 是&quot;季节性的&quot;，seasonable 是&quot;合时令的、适宜的&quot;。</li><li>拼写 seasonal，不是 <s>seasonnal</s>。</li><li>描述数据波动用 seasonal variation／fluctuation。</li></ul></div><div class="vocab-card"><h2 id="productive" tabindex="-1"><a class="header-anchor" href="#productive"><span>Productive</span></a></h2><p class="vc-meta"><strong>/prəˈdʌktɪv/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>多产的，高产的（土地、工厂、人）</li><li>富有成效的（讨论、时间）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>productive land</td><td>高产土地</td></tr><tr><td>a productive meeting</td><td>富有成效的会议</td></tr><tr><td>highly productive</td><td>高产的</td></tr><tr><td>productive capacity</td><td>生产能力</td></tr><tr><td>remain productive</td><td>保持高产</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the productive capacity of farmland before and after irrigation.</p><blockquote><p>该图比较了灌溉前后农田的生产能力。</p></blockquote><p><strong>Writing Task 2</strong> A shorter working week can be more productive if it cuts meetings rather than focused work.</p><blockquote><p>如果缩短工周减少的是会议而非专注工作，它可能更有生产力。</p></blockquote><p><strong>Speaking</strong> I get more done in two focused hours than in a whole productive-looking day.</p><blockquote><p>我两小时专注干的活，比看起来忙了一整天还多。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>fertile</td><td>肥沃的</td><td>只用于土地与想象力</td></tr><tr><td>prolific</td><td>多产的</td><td>多用于作家、艺术家</td></tr><tr><td>efficient</td><td>高效的</td><td>强调投入产出比，不强调总量</td></tr><tr><td>fruitful</td><td>有成果的</td><td>多用于讨论与努力</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> pro-（向前）+ ducere（引导）+ -ive</li><li><strong>Family:</strong> productive 多产的 / produce 生产 / product 产品 / productivity 生产率</li><li><strong>Memory Tip:</strong> ducere 是&quot;引导&quot;：produce 是&quot;引出来&quot;，所以 productive 就是&quot;能引出很多东西的&quot;。productivity 是经济学高频词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 efficient 区分：productive 看&quot;产出多少&quot;，efficient 看&quot;投入多少&quot;。</li><li>名词是 productivity：<s>productiveness</s> 少用。</li><li>拼写 productive，不是 <s>productiv</s>。</li></ul></div><div class="vocab-card"><h2 id="efficient" tabindex="-1"><a class="header-anchor" href="#efficient"><span>Efficient</span></a></h2><p class="vc-meta"><strong>/ɪˈfɪʃnt/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>高效的，效率高的（以较少投入获得较多产出）</li><li>（机器、系统）运转良好的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>energy-efficient</td><td>节能的</td></tr><tr><td>an efficient use of resources</td><td>资源的有效利用</td></tr><tr><td>highly efficient</td><td>效率很高</td></tr><tr><td>cost-efficient</td><td>成本效益高的</td></tr><tr><td>efficient transport</td><td>高效的交通</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the energy-efficient appliances with older models of the same size.</p><blockquote><p>该图比较了节能家电与同尺寸旧型号的能耗。</p></blockquote><p><strong>Writing Task 2</strong> Dense cities are more energy-efficient per person, which is why urbanisation can lower national emissions.</p><blockquote><p>高密度城市的人均能耗更低，因此城市化可以降低全国排放。</p></blockquote><p><strong>Speaking</strong> The new heating system is far more efficient — the bills dropped by a third.</p><blockquote><p>新供暖系统效率高得多，账单降了三分之一。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>effective</td><td>有效的</td><td>强调达到目的，不管成本</td></tr><tr><td>economical</td><td>节省的</td><td>强调省钱省资源</td></tr><tr><td>streamlined</td><td>精简的</td><td>强调流程简化</td></tr><tr><td>productive</td><td>高产的</td><td>强调产出总量</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> ex-（出）+ facere（做）+ -ient → 做出成效的</li><li><strong>Family:</strong> efficient 高效的 / efficiency 效率 / efficient 与 effective 常对比 / factory 工厂（同源 facere）</li><li><strong>Memory Tip:</strong> efficient 与 effective 的经典区别：effective 是&quot;有没有用&quot;，efficient 是&quot;省不省力&quot;。写作中两者常被混用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 effective 区分：effective 管&quot;效果&quot;，efficient 管&quot;成本&quot;。</li><li>名词是 efficiency：energy efficiency 能效。</li><li>拼写 efficient，双 f，不是 <s>eficient</s>。</li></ul></div><div class="vocab-card"><h2 id="effective" tabindex="-1"><a class="header-anchor" href="#effective"><span>Effective</span></a></h2><p class="vc-meta"><strong>/ɪˈfektɪv/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>有效的，起作用的</li><li>生效的（法律、规定）；（人）实际上的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>an effective solution</td><td>有效的解决方案</td></tr><tr><td>cost-effective</td><td>成本效益好的</td></tr><tr><td>take effect / become effective</td><td>生效</td></tr><tr><td>highly effective</td><td>非常有效</td></tr><tr><td>effective communication</td><td>有效沟通</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the effectiveness of three methods of reducing household waste.</p><blockquote><p>该图比较了三种减少家庭垃圾方法的有效性。</p></blockquote><p><strong>Writing Task 2</strong> Information campaigns are cheap but rarely effective without a price signal behind them.</p><blockquote><p>宣传推广成本低，但若背后没有价格信号，很少真正有效。</p></blockquote><p><strong>Speaking</strong> The spray is effective for about a week, then the ants come back.</p><blockquote><p>那个喷雾大约有效一周，然后蚂蚁又回来了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>efficient</td><td>高效的</td><td>看投入产出比，不看是否奏效</td></tr><tr><td>efficacious</td><td>有疗效的</td><td>医学用语，较正式</td></tr><tr><td>successful</td><td>成功的</td><td>泛称，不强调机制</td></tr><tr><td>operative</td><td>生效的</td><td>只对应法律义项</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> ex-（出）+ facere（做）+ -ive → 能做出结果的</li><li><strong>Family:</strong> effective 有效的 / effect 效果 / effectiveness 有效性 / effectively 实际上；有效地</li><li><strong>Memory Tip:</strong> effect 是&quot;效果&quot;，所以 effective 是&quot;有效果的&quot;。become effective 是&quot;生效&quot;，法律文本常用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 efficient 区分：effective 看结果，efficient 看成本。</li><li>名词用 effectiveness，不用 <s>effectivity</s>（少用）。</li><li>拼写 effective，双 f。</li></ul></div><div class="vocab-card"><h2 id="minimal" tabindex="-1"><a class="header-anchor" href="#minimal"><span>Minimal</span></a></h2><p class="vc-meta"><strong>/ˈmɪnɪml/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>最小的，极小的（程度、数量）</li><li>极简的（设计风格）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>minimal impact</td><td>极小的影响</td></tr><tr><td>minimal cost</td><td>最低成本</td></tr><tr><td>minimal maintenance</td><td>几乎无需维护</td></tr><tr><td>minimal design</td><td>极简设计</td></tr><tr><td>keep to a minimum</td><td>保持在最低限度</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows that the new process has minimal water use compared with the old one.</p><blockquote><p>该图显示新工艺相比旧工艺用水极少。</p></blockquote><p><strong>Writing Task 2</strong> A policy with minimal enforcement is barely a policy at all.</p><blockquote><p>一项几乎没有执行的政策，几乎算不上政策。</p></blockquote><p><strong>Speaking</strong> The flat is minimal — a bed, a table, and not much else.</p><blockquote><p>那套房子极简，一张床、一张桌子，别的没什么了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>minimum</td><td>最低的</td><td>指下限值，常用于数据</td></tr><tr><td>negligible</td><td>可忽略的</td><td>强调小到不必计算</td></tr><tr><td>slight</td><td>轻微的</td><td>用于变化与差异</td></tr><tr><td>marginal</td><td>边缘的；微小的</td><td>强调接近临界，收益很小</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>minimus</em>（最小）</li><li><strong>Family:</strong> minimal 最小的 / minimum 最低限度 / minimise 使最小化 / minor 较小的</li><li><strong>Memory Tip:</strong> minimal 是形容词，minimum 多作名词或定语指&quot;最低值&quot;。写作中 minimal impact 比 very small impact 更正式。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 minimum 区分：minimum wage（最低工资）用 minimum，不用 <s>minimal wage</s>。</li><li>拼写 minimal，不是 <s>minimal</s> 的双 m 变体 <s>minnimal</s>。</li><li>动词是 minimise／minimize：<s>minimalise</s> ✘。</li></ul></div><div class="vocab-card"><h2 id="maximal" tabindex="-1"><a class="header-anchor" href="#maximal"><span>Maximal</span></a></h2><p class="vc-meta"><strong>/ˈmæksɪml/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>最大的，最大限度的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>maximal efficiency</td><td>最高效率</td></tr><tr><td>maximal use of</td><td>最大限度地利用</td></tr><tr><td>maximal impact</td><td>最大影响</td></tr><tr><td>maximal growth</td><td>最大增长</td></tr><tr><td>maximal benefit</td><td>最大收益</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the conditions under which maximal growth occurs.</p><blockquote><p>该图显示了最大增长出现的条件。</p></blockquote><p><strong>Writing Task 2</strong> Maximising yields is not the same as maximising welfare, because the two use land differently.</p><blockquote><p>产量最大化不等于福利最大化，因为两者对土地的用法不同。</p></blockquote><p><strong>Speaking</strong> The plan is designed for maximal flexibility, which in practice means nobody knows what&#39;s happening.</p><blockquote><p>这个方案追求最大灵活性，实际效果是没人知道在发生什么。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>maximum</td><td>最大的</td><td>更常用，指具体上限值</td></tr><tr><td>optimum</td><td>最优的</td><td>强调最佳，不是最大</td></tr><tr><td>peak</td><td>峰值的</td><td>指变化曲线的高点</td></tr><tr><td>ultimate</td><td>最终的</td><td>强调终点，不指数量</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>maximus</em>（最大）</li><li><strong>Family:</strong> maximal 最大的 / maximum 最大值 / maximise 使最大化 / major 较大的</li><li><strong>Memory Tip:</strong> maximal 与 maximum 的关系类似 minimal 与 minimum。注意 optimum 是&quot;最优&quot;而非&quot;最大&quot;，写作中别混。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 maximum 区分：maximum speed（最高速度）用 maximum 更自然。</li><li>与 optimal 区分：maximal 是&quot;最大&quot;，optimal 是&quot;最佳&quot;。</li><li>拼写 maximal，不是 <s>maximmal</s>。</li></ul></div><div class="vocab-card"><h2 id="optimal" tabindex="-1"><a class="header-anchor" href="#optimal"><span>Optimal</span></a></h2><p class="vc-meta"><strong>/ˈɒptɪməl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>最佳的，最适宜的（在给定条件下效果最好）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>optimal conditions</td><td>最适条件</td></tr><tr><td>the optimal temperature</td><td>最适温度</td></tr><tr><td>optimal use of resources</td><td>资源的最优利用</td></tr><tr><td>near-optimal</td><td>接近最优的</td></tr><tr><td>optimal outcome</td><td>最佳结果</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows that the optimal temperature for enzyme activity is around 37 degrees.</p><blockquote><p>该图显示酶活性的最适温度约为 37 度。</p></blockquote><p><strong>Writing Task 2</strong> There is no single optimal policy: what works in a dense city fails in a dispersed rural region.</p><blockquote><p>不存在单一的最优政策：在高密度城市有效的做法，在分散的乡村地区会失效。</p></blockquote><p><strong>Speaking</strong> The plants are in optimal conditions now, so any change will probably make things worse.</p><blockquote><p>这些植物现在条件最佳，任何改动大概都只会更糟。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>ideal</td><td>理想的</td><td>更主观，强调完美</td></tr><tr><td>best</td><td>最好的</td><td>口语，最通用</td></tr><tr><td>optimum</td><td>最适的</td><td>名词与形容词同形，学术常用</td></tr><tr><td>favourable</td><td>有利的</td><td>强调条件有利，不强调&quot;最优&quot;</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>optimus</em>（最好的）</li><li><strong>Family:</strong> optimal 最佳的 / optimum 最适值 / optimise 优化 / optimism 乐观（同源&quot;最好&quot;）</li><li><strong>Memory Tip:</strong> optimus 是&quot;最好&quot;：optimal 是最佳，optimise 是优化，optimism 是总往好处想。一条词根记三个高频词。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 maximal 区分：optimal 是&quot;最佳&quot;，不是&quot;最大&quot;。</li><li>名词常写 optimum：the optimum temperature。</li><li>拼写 optimal，不是 <s>optimmal</s>。</li></ul></div><div class="vocab-card"><h2 id="considerable" tabindex="-1"><a class="header-anchor" href="#considerable"><span>Considerable</span></a></h2><p class="vc-meta"><strong>/kənˈsɪdərəbl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>相当大的，相当多的（数量、程度）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>considerable variation</td><td>相当大的差异</td></tr><tr><td>considerable amount of</td><td>相当多的</td></tr><tr><td>considerable progress</td><td>相当大的进展</td></tr><tr><td>at considerable cost</td><td>以相当大的代价</td></tr><tr><td>considerable influence</td><td>相当大的影响</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows considerable variation in rainfall between the two regions.</p><blockquote><p>该图显示了两个地区降雨量差异相当大。</p></blockquote><p><strong>Writing Task 2</strong> Reducing emissions will require considerable upfront investment before any savings appear.</p><blockquote><p>减排需要在见到任何节省之前投入相当可观的前期资金。</p></blockquote><p><strong>Speaking</strong> There&#39;s considerable pressure to say yes, even when the answer should be no.</p><blockquote><p>说&quot;好&quot;的压力相当大，即便答案应该是否定的。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>substantial</td><td>大量的</td><td>更正式，强调体量实在</td></tr><tr><td>significant</td><td>显著的</td><td>强调重要性，也可指数量</td></tr><tr><td>sizeable</td><td>相当大的</td><td>多用于具体数量</td></tr><tr><td>moderate</td><td>中等的</td><td>程度更轻</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> consider（考虑）+ -able → 值得考虑的 → 相当多的</li><li><strong>Family:</strong> considerable 相当大的 / consider 考虑 / considerably 相当地 / considerate 体贴的</li><li><strong>Memory Tip:</strong> 注意 considerable（相当大的）与 considerate（体贴的）是两个词。写作中 considerable 修饰不可数名词最稳妥。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>与 considerate 区分：considerate 是&quot;体贴的&quot;，不是&quot;相当大的&quot;。</li><li>修饰不可数：considerable influence；可数复数也可：considerable differences。</li><li>拼写 considerable，不是 <s>considerble</s>。</li></ul></div><div class="vocab-card"><h2 id="immense" tabindex="-1"><a class="header-anchor" href="#immense"><span>Immense</span></a></h2><p class="vc-meta"><strong>/ɪˈmens/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>巨大的，极大的（规模、程度）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>immense value</td><td>巨大价值</td></tr><tr><td>immense pressure</td><td>巨大压力</td></tr><tr><td>immense scale</td><td>巨大规模</td></tr><tr><td>an immense amount of</td><td>大量的</td></tr><tr><td>immense benefit</td><td>巨大益处</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the immense difference in water use between the two farming methods.</p><blockquote><p>该图显示了两种耕作方式在用水上的巨大差异。</p></blockquote><p><strong>Writing Task 2</strong> The benefits of early education are immense but appear decades after the spending.</p><blockquote><p>早期教育的收益巨大，但要在支出数十年后才显现。</p></blockquote><p><strong>Speaking</strong> The relief was immense — I hadn&#39;t realised how worried I was.</p><blockquote><p>那种如释重负感是巨大的，我之前没意识到自己有多担心。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>enormous</td><td>巨大的</td><td>最常用，语气强</td></tr><tr><td>vast</td><td>广阔的</td><td>强调面积与范围</td></tr><tr><td>tremendous</td><td>极大的</td><td>可指数量与程度，偏口语</td></tr><tr><td>massive</td><td>大规模的</td><td>强调体量与块头</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁语 <em>immensus</em>（无法测量的）← im-（不）+ metiri（测量）</li><li><strong>Family:</strong> immense 巨大的 / immensely 极其 / immensity 巨大 / measure 测量</li><li><strong>Memory Tip:</strong> 字面是&quot;量不出来&quot;——大到没法测量，所以是&quot;巨大&quot;。与 metiri（测量）同根，measure 也在这一族。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>修饰不可数或抽象名词最常见：immense value、immense pressure。</li><li>与 massive 区分：immense 偏&quot;程度极大&quot;，massive 偏&quot;体量巨大&quot;。</li><li>拼写 immense，双 m 双 s。</li></ul></div><div class="vocab-card"><h2 id="massive" tabindex="-1"><a class="header-anchor" href="#massive"><span>Massive</span></a></h2><p class="vc-meta"><strong>/ˈmæsɪv/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>巨大的，大规模的，大量的</li><li>严重的，重大的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>massive scale</td><td>巨大规模</td></tr><tr><td>a massive increase</td><td>大幅增长</td></tr><tr><td>massive investment</td><td>大规模投资</td></tr><tr><td>massive damage</td><td>严重破坏</td></tr><tr><td>massive open online course</td><td>大型开放式网络课程</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows a massive increase in container traffic after 1990.</p><blockquote><p>该图显示了 1990 年后集装箱运输量的大幅增长。</p></blockquote><p><strong>Writing Task 2</strong> Building on flood plains requires massive spending on defences that will only be tested by the next extreme event.</p><blockquote><p>在洪泛区建设需要巨额防洪投入，而这些设施只会被下一次极端事件检验。</p></blockquote><p><strong>Speaking</strong> The concert was massive — forty thousand people and one very small stage.</p><blockquote><p>那场演出规模巨大，四万人，一个小得可怜的舞台。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>huge</td><td>巨大的</td><td>口语，最通用</td></tr><tr><td>immense</td><td>极大的</td><td>偏程度，不强调体量</td></tr><tr><td>enormous</td><td>巨大的</td><td>语气强，可指数与量</td></tr><tr><td>extensive</td><td>广泛的</td><td>强调覆盖范围</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> mass（团块、大量）+ -ive</li><li><strong>Family:</strong> massive 巨大的 / mass 大量；质量 / mass-produced 大批量生产的</li><li><strong>Memory Tip:</strong> mass 是&quot;一团、大量&quot;，所以 massive 是&quot;成块的巨大&quot;。写作中 a massive increase 比 a big increase 更有分量。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可修饰可数与不可数：massive increase、massive investments。</li><li>与 extensive 区分：massive 偏体量，extensive 偏范围。</li><li>拼写 massive，双 s。</li></ul></div><div class="vocab-card"><h2 id="favourable" tabindex="-1"><a class="header-anchor" href="#favourable"><span>Favourable</span></a></h2><p class="vc-meta"><strong>/ˈfeɪvərəbl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>有利的，适宜的（条件、环境）</li><li>赞同的，肯定的（评价、反应）</li><li>美式拼写 favorable</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>favourable conditions</td><td>有利条件</td></tr><tr><td>a favourable response</td><td>肯定的回应</td></tr><tr><td>favourable to</td><td>有利于</td></tr><tr><td>favourable weather</td><td>宜人的天气</td></tr><tr><td>favourable impression</td><td>良好印象</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows how favourable growing conditions vary across the region.</p><blockquote><p>该图显示了该地区适宜生长条件的变化。</p></blockquote><p><strong>Writing Task 2</strong> Public opinion was favourable until the costs became clear, which is a common pattern for environmental policy.</p><blockquote><p>在成本明确之前，公众舆论是支持的，这是环境政策常见的模式。</p></blockquote><p><strong>Speaking</strong> The reviews were surprisingly favourable, given how rushed the whole thing was.</p><blockquote><p>考虑到整个过程有多赶，那些评价出乎意料地正面。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>advantageous</td><td>有利的</td><td>强调带来优势，较正式</td></tr><tr><td>beneficial</td><td>有益的</td><td>强调带来好处，可用于健康</td></tr><tr><td>positive</td><td>积极的</td><td>泛称，不含&quot;条件适宜&quot;义</td></tr><tr><td>conducive</td><td>有助于的</td><td>多与 to 连用，指环境</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> favour（恩惠、支持）+ -able</li><li><strong>Family:</strong> favourable 有利的 / favour 偏爱；赞成 / favourite 最喜欢的 / favourably 有利地</li><li><strong>Memory Tip:</strong> 英式 -ourable、美式 -orable，全文统一。表示&quot;有利于&quot;用 favourable to／for，注意介词搭配。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>英式 favourable／美式 favorable，别混用。</li><li>表示&quot;有利于&quot;：conditions favourable to growth。</li><li>拼写 favourable，中间是 -vour-。</li></ul></div><div class="vocab-card"><h2 id="outcome" tabindex="-1"><a class="header-anchor" href="#outcome"><span>Outcome</span></a></h2><p class="vc-meta"><strong>/ˈaʊtkʌm/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>结果，成果（行动、过程、事件的最终结果）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the outcome of</td><td>……的结果</td></tr><tr><td>a positive outcome</td><td>积极结果</td></tr><tr><td>learning outcomes</td><td>学习成果</td></tr><tr><td>the likely outcome</td><td>可能的结果</td></tr><tr><td>influence the outcome</td><td>影响结果</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart compares the outcomes of two restoration projects after five years.</p><blockquote><p>该图比较了两个修复项目五年后的结果。</p></blockquote><p><strong>Writing Task 2</strong> Judging a policy by its intentions rather than its outcomes is how bad policies survive.</p><blockquote><p>用意图而非结果来评判政策，正是坏政策得以存续的原因。</p></blockquote><p><strong>Speaking</strong> The outcome was better than we deserved, honestly.</p><blockquote><p>说实话，那个结果比我们应得的要好。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>result</td><td>结果</td><td>最通用，中性</td></tr><tr><td>consequence</td><td>后果</td><td>常含负面意味</td></tr><tr><td>upshot</td><td>结果</td><td>口语，指最终结论</td></tr><tr><td>effect</td><td>效果</td><td>强调因果作用</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> out（出）+ come（来）→ 出来的东西</li><li><strong>Family:</strong> outcome 结果 / come out 出现 / income 收入 / overcome 克服</li><li><strong>Memory Tip:</strong> 字面&quot;出来的东西&quot;就是结果。outcome 比 result 更强调&quot;过程之后的最终状态&quot;，政策与教育语境常用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a positive outcome、learning outcomes。</li><li>与 consequence 区分：outcome 中性，consequence 常暗示负面。</li><li>拼写 outcome 连写。</li></ul></div>`,27)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};